question.solution:
def delete_seq_list(arr, pos):
    if pos < 0 or pos >= len(arr):
        return False
    for i in range(pos, len(arr) - 1):
        arr[i] = arr[i + 1]
    arr.pop()
    return True

data = [10, 20, 30, 40, 50]
print(delete_seq_list(data, 1), data)
print(delete_seq_list(data, 10), data)
